export interface Question {
  id: string;
  institution: string;
  year: number;
  specialty: Specialty;
  text: string;
  options: string[];
  correctAnswer: number | null;
  explanation: string;
}

export interface SummaryModule {
  id: string;
  title: string;
  description: string;
  price: number;
  oldPrice: number;
  icon: string;
  color: string;
}

export interface Testimonial {
  name: string;
  text: string;
  avatar: string;
}

import { useState, useEffect } from 'react';
import { Question } from '../types';

interface QuizEngineProps {
  questions: Question[];
  onFinish: () => void;
  onGoToSummaries: () => void;
}

const QuizEngine: React.FC<QuizEngineProps> = ({ questions, onFinish, onGoToSummaries }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<(number | null)[]>(new Array(questions.length).fill(null));
  const [showExplanation, setShowExplanation] = useState(false);
  const [showResults, setShowResults] = useState(false);
  const [showMidQuizOffer, setShowMidQuizOffer] = useState(false);

  const currentQuestion = questions[currentIndex];
  const isAnswered = answers[currentIndex] !== null;

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [currentIndex, showResults]);

  const handleAnswer = (optionIndex: number) => {
    if (isAnswered) return;
    const newAnswers = [...answers];
    newAnswers[currentIndex] = optionIndex;
    setAnswers(newAnswers);
    setShowExplanation(true);

    // Oferta a cada 20 questões respondidas
    const currentAnsweredCount = newAnswers.filter(a => a !== null).length;
    if (currentAnsweredCount > 0 && currentAnsweredCount % 20 === 0) {
      setTimeout(() => setShowMidQuizOffer(true), 1200);
    }
  };

  const nextQuestion = () => {
    if (currentIndex < questions.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setShowExplanation(answers[currentIndex + 1] !== null);
    } else {
      setShowResults(true);
    }
  };

  const prevQuestion = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setShowExplanation(answers[currentIndex - 1] !== null);
    }
  };

  const correctAnswersCount = answers.filter((a, i) => a !== null && a === questions[i].correctAnswer).length;
  const answeredCount = answers.filter(a => a !== null).length;
  const progressPercentage = Math.round((answeredCount / questions.length) * 100);
  const scorePercentage = Math.round((correctAnswersCount / questions.length) * 100);

  const cutOffScores = [
    { name: 'Dermatologia', score: '928.95' },
